def change(name,old,new):
    path='scripts/forest/'+name+'.gd'
    if path not in before:before[path]=(ROOT/path).read_text();after[path]=before[path]
    assert after[path].count(old)==1,(path,old,after[path].count(old))
    after[path]=after[path].replace(old,new,1)

